import{_ as i,o as s,c as e,ai as n}from"./chunks/framework.CaiDwmc7.js";const p=JSON.parse('{"title":"Panduan Resolusi Konflik Git (Unrelated Histories)","description":"","frontmatter":{},"headers":[],"relativePath":"git-resolusi-konflik.md","filePath":"git-resolusi-konflik.md"}'),l={name:"git-resolusi-konflik.md"};function t(h,a,k,r,o,d){return s(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="panduan-resolusi-konflik-git-unrelated-histories" tabindex="-1">Panduan Resolusi Konflik Git (Unrelated Histories) <a class="header-anchor" href="#panduan-resolusi-konflik-git-unrelated-histories" aria-label="Permalink to “Panduan Resolusi Konflik Git (Unrelated Histories)”">​</a></h1><p>Dokumen ini menjelaskan cara menangani masalah <code>rejected - non-fast-forward</code> atau <code>fatal: refusing to merge unrelated histories</code> yang terjadi ketika mencoba push/pull antara repositori lokal dan remote yang memiliki riwayat commit yang berbeda.</p><h2 id="_1-masalah-rejected-non-fast-forward" tabindex="-1">1. Masalah: &quot;Rejected - Non-Fast-Forward&quot; <a class="header-anchor" href="#_1-masalah-rejected-non-fast-forward" aria-label="Permalink to “1. Masalah: &quot;Rejected - Non-Fast-Forward&quot;”">​</a></h2><p>Masalah ini biasanya terjadi jika:</p><ul><li>Anda baru saja menginisialisasi repositori lokal baru dan mencoba push ke repositori remote yang sudah ada isinya.</li><li>Seseorang telah melakukan <code>force push</code> ke remote.</li><li>Anda mencoba menggabungkan dua proyek yang tidak berbagi commit awal yang sama.</li></ul><h2 id="_2-solusi-langkah-demi-langkah" tabindex="-1">2. Solusi Langkah-Demi-Langkah <a class="header-anchor" href="#_2-solusi-langkah-demi-langkah" aria-label="Permalink to “2. Solusi Langkah-Demi-Langkah”">​</a></h2><h3 id="langkah-1-tarik-pull-perubahan-dari-remote" tabindex="-1">Langkah 1: Tarik (Pull) Perubahan dari Remote <a class="header-anchor" href="#langkah-1-tarik-pull-perubahan-dari-remote" aria-label="Permalink to “Langkah 1: Tarik (Pull) Perubahan dari Remote”">​</a></h3><p>Gunakan flag <code>--allow-unrelated-histories</code> untuk memaksa Git menggabungkan dua riwayat yang berbeda.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --allow-unrelated-histories</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-rebase</span></span></code></pre></div><h3 id="langkah-2-resolusi-konflik-jika-ada" tabindex="-1">Langkah 2: Resolusi Konflik (Jika Ada) <a class="header-anchor" href="#langkah-2-resolusi-konflik-jika-ada" aria-label="Permalink to “Langkah 2: Resolusi Konflik (Jika Ada)”">​</a></h3><p>Jika terjadi konflik massal dan Anda ingin <strong>mengutamakan versi lokal Anda</strong> , gunakan perintah berikut:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Menggunakan versi lokal untuk semua file yang konflik</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ours</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ATAU jika ingin memilih manual per file:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># git checkout --ours path/to/file.php</span></span></code></pre></div><p>Jika Anda ingin <strong>mengutamakan versi remote</strong> , gunakan:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --theirs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><h3 id="langkah-3-commit-hasil-penggabungan" tabindex="-1">Langkah 3: Commit Hasil Penggabungan <a class="header-anchor" href="#langkah-3-commit-hasil-penggabungan" aria-label="Permalink to “Langkah 3: Commit Hasil Penggabungan”">​</a></h3><p>Setelah konflik diselesaikan (baik via <code>checkout --ours</code> atau manual), tambahkan file ke staging dan commit.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Merge remote-tracking branch &#39;origin/main&#39; with local changes (resolved conflicts)&quot;</span></span></code></pre></div><h3 id="langkah-4-push-ke-remote" tabindex="-1">Langkah 4: Push ke Remote <a class="header-anchor" href="#langkah-4-push-ke-remote" aria-label="Permalink to “Langkah 4: Push ke Remote”">​</a></h3><p>Sekarang riwayat sudah tergabung, Anda bisa melakukan push secara normal.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span></code></pre></div><h2 id="_3-tips-pencegahan-di-masa-depan" tabindex="-1">3. Tips Pencegahan di Masa Depan <a class="header-anchor" href="#_3-tips-pencegahan-di-masa-depan" aria-label="Permalink to “3. Tips Pencegahan di Masa Depan”">​</a></h2><ul><li>Selalu lakukan <code>git pull</code> sebelum mulai bekerja untuk memastikan lokal Anda sinkron dengan remote.</li><li>Jika Anda membuat repositori baru di GitHub dengan file <code>README</code> atau <code>LICENSE</code>, segera lakukan <code>git pull origin main --allow-unrelated-histories</code> setelah <code>git remote add origin</code>.</li><li>Hindari penggunaan <code>git push -f</code> (force push) kecuali Anda benar-benar yakin, karena ini akan merusak riwayat rekan tim lainnya.</li></ul><hr><p><em>Dibuat untuk dokumentasi internal proyek Avery PHP.</em></p>`,24)])])}const u=i(l,[["render",t]]);export{p as __pageData,u as default};
